class Solution {
public:
    int countTexts(string pressedKeys) {
        const long long MOD = 1e9 + 7;
        int n = pressedKeys.size();
        vector<long long> f3(n + 1, 0), f4(n + 1, 0);
        f3[0] = f4[0] = 1;
        for (int i = 1; i <= n; i++) {
            f3[i] = f3[i-1];
            if (i > 1) f3[i] += f3[i-2];
            if (i > 2) f3[i] += f3[i-3];
            f3[i] %= MOD;
            f4[i] = f4[i-1];
            if (i > 1) f4[i] += f4[i-2];
            if (i > 2) f4[i] += f4[i-3];
            if (i > 3) f4[i] += f4[i-4];
            f4[i] %= MOD;
        }
        long long ans = 1;
        int i = 0;
        while (i < n) {
            int j = i;
            while (j < n && pressedKeys[j] == pressedKeys[i]) j++;
            bool four = pressedKeys[i] == '7' || pressedKeys[i] == '9';
            ans = ans * (four ? f4[j - i] : f3[j - i]) % MOD;
            i = j;
        }
        return (int)ans;
    }
};

