class Solution {
    public int countTexts(String pressedKeys) {
        final long MOD = 1_000_000_007L;
        int n = pressedKeys.length();
        long[] f3 = new long[n + 1], f4 = new long[n + 1];
        f3[0] = f4[0] = 1;
        for (int i = 1; i <= n; i++) {
            f3[i] = f3[i-1];
            if (i > 1) f3[i] += f3[i-2];
            if (i > 2) f3[i] += f3[i-3];
            f3[i] %= MOD;
            f4[i] = f4[i-1];
            if (i > 1) f4[i] += f4[i-2];
            if (i > 2) f4[i] += f4[i-3];
            if (i > 3) f4[i] += f4[i-4];
            f4[i] %= MOD;
        }
        long ans = 1;
        int i = 0;
        while (i < n) {
            int j = i;
            while (j < n && pressedKeys.charAt(j) == pressedKeys.charAt(i)) j++;
            char c = pressedKeys.charAt(i);
            ans = ans * (c == '7' || c == '9' ? f4[j - i] : f3[j - i]) % MOD;
            i = j;
        }
        return (int) ans;
    }
}

