var countTexts = function(pressedKeys) {
    const MOD = 1e9 + 7;
    const n = pressedKeys.length;
    const f3 = [1], f4 = [1];
    for (let i = 1; i <= n; i++) {
        f3[i] = f3[i-1];
        if (i > 1) f3[i] += f3[i-2];
        if (i > 2) f3[i] += f3[i-3];
        f3[i] %= MOD;
        f4[i] = f4[i-1];
        if (i > 1) f4[i] += f4[i-2];
        if (i > 2) f4[i] += f4[i-3];
        if (i > 3) f4[i] += f4[i-4];
        f4[i] %= MOD;
    }
    let ans = 1, i = 0;
    while (i < n) {
        let j = i;
        while (j < n && pressedKeys[j] === pressedKeys[i]) j++;
        const c = pressedKeys[i];
        ans = ans * ((c === '7' || c === '9') ? f4[j - i] : f3[j - i]) % MOD;
        i = j;
    }
    return ans;
};
